CREATE TABLE t_p23442598_alumni_network_app.users (id SERIAL PRIMARY KEY, name VARCHAR(100) NOT NULL, initials VARCHAR(4) NOT NULL, color VARCHAR(80) NOT NULL DEFAULT 'from-violet-500 to-purple-700', school VARCHAR(100) NOT NULL DEFAULT '', year VARCHAR(4) NOT NULL DEFAULT '', email VARCHAR(150) NOT NULL DEFAULT '', status VARCHAR(20) NOT NULL DEFAULT 'active', posts_count INT NOT NULL DEFAULT 0, friends_count INT NOT NULL DEFAULT 0, joined_at TIMESTAMP NOT NULL DEFAULT NOW())
